#include "nexa/c_api.h"
#include <cassert>
#include <cstring>
#include <iostream>
#include <array>
#include <cstdio>
#include <filesystem>
int main(){auto*c=nexa_context_create();assert(c);uint64_t id=0;assert(nexa_session_create(c,"ffi-test",256,&id)==0);assert(nexa_session_load_assembly(c,id,"LOAD A, 12\nHALT\n")==0);assert(nexa_session_start(c,id)==0);NexaSessionState state=NEXA_READY;assert(nexa_session_run(c,id,10,&state)==0&&state==NEXA_HALTED);NexaSessionInfo info{};assert(nexa_session_info(c,id,&info)==0);size_t sessionCount=0;assert(nexa_session_list(c,nullptr,0,&sessionCount)==0&&sessionCount==1);NexaSessionInfo listed{};assert(nexa_session_list(c,&listed,1,&sessionCount)==0&&listed.id==id);assert(nexa_session_list(c,&listed,0,&sessionCount)<0&&sessionCount==1);assert(info.ram_bytes==256&&info.halted&&info.instructions==2);uint8_t val=0;assert(nexa_memory_read(c,id,0,&val)==0);assert(nexa_memory_write(c,id,3,99)==0);assert(nexa_memory_read(c,id,3,&val)==0&&val==99);assert(nexa_keyboard_input(c,id,"hi\n")==0);assert(nexa_breakpoint_set(c,id,0)==0);assert(nexa_breakpoint_clear(c,id,0)==0);int pixel=0;assert(nexa_framebuffer_draw(c,id,4,5,1)==0);assert(nexa_framebuffer_get(c,id,4,5,&pixel)==0&&pixel==1);assert(nexa_framebuffer_draw(c,id,4,5,0)==0);assert(nexa_framebuffer_get(c,id,4,5,&pixel)==0&&pixel==0);auto diskPath=(std::filesystem::temp_directory_path()/"nexa-c-api-test.disk").string();assert(nexa_disk_attach(c,id,diskPath.c_str(),1024)==0);size_t sectors=0;assert(nexa_disk_sector_count(c,id,&sectors)==0&&sectors==2);std::array<uint8_t,512> sector{};sector[0]=0x4e;assert(nexa_disk_write_sector(c,id,1,sector.data())==0);assert(nexa_disk_flush(c,id)==0);sector.fill(0);assert(nexa_disk_read_sector(c,id,1,sector.data())==0&&sector[0]==0x4e);assert(nexa_disk_read_sector(c,id,2,sector.data())<0);auto disk2=(std::filesystem::temp_directory_path()/"nexa-c-api-test-2.disk").string();assert(nexa_disk_attach_device(c,id,7,disk2.c_str(),1536)==0);size_t deviceCount=0;assert(nexa_disk_device_count(c,id,&deviceCount)==0&&deviceCount==2);size_t secondSectors=0;assert(nexa_disk_sector_count_device(c,id,7,&secondSectors)==0&&secondSectors==3);assert(nexa_memory_write(c,id,128,0x6b)==0);assert(nexa_disk_write_from_guest(c,id,7,2,128)==0);assert(nexa_disk_flush_device(c,id,7)==0);assert(nexa_memory_write(c,id,128,0)==0);assert(nexa_disk_read_to_guest(c,id,7,2,128)==0);assert(nexa_memory_read(c,id,128,&val)==0&&val==0x6b);assert(nexa_disk_detach(c,id,7,1)==0);assert(nexa_disk_device_count(c,id,&deviceCount)==0&&deviceCount==1);assert(nexa_disk_sector_count_device(c,id,7,&secondSectors)<0);std::remove(disk2.c_str());assert(nexa_session_remove(c,id)==0);uint64_t guestId=0;assert(nexa_session_create(c,"guest-disk",512,&guestId)==0);auto guestDiskPath=(std::filesystem::temp_directory_path()/"nexa-guest-disk-test.disk").string();assert(nexa_disk_attach(c,guestId,guestDiskPath.c_str(),1024)==0);assert(nexa_memory_write(c,guestId,0,0x5a)==0);assert(nexa_session_load_assembly(c,guestId,"LOAD A, 90\nSTORE [0]\nLOAD A, 5\nLOAD B, 1\nSYS\nHALT\n")==0);assert(nexa_session_start(c,guestId)==0);assert(nexa_session_run(c,guestId,10,&state)==0&&state==NEXA_HALTED);assert(nexa_disk_flush(c,guestId)==0);sector.fill(0);assert(nexa_disk_read_sector(c,guestId,1,sector.data())==0&&sector[0]==0x5a);assert(nexa_session_reset(c,guestId)==0);assert(nexa_session_load_assembly(c,guestId,"LOAD A, 4\nLOAD B, 1\nSYS\nHALT\n")==0);assert(nexa_session_start(c,guestId)==0);assert(nexa_session_run(c,guestId,10,&state)==0&&state==NEXA_HALTED);assert(nexa_memory_read(c,guestId,0,&val)==0&&val==0x5a);assert(nexa_session_remove(c,guestId)==0);std::remove(guestDiskPath.c_str());std::remove(diskPath.c_str());assert(nexa_session_info(c,id,&info)<0);assert(std::strlen(nexa_last_error(c))>0);nexa_context_destroy(c);std::cout<<"C API tests passed\n";}
